solutionCode:
def coin_change(coins, amount):
    table = [amount + 1] * (amount + 1)
    table[0] = 0
    for total in range(1, amount + 1):
        for coin in coins:
            if coin <= total and table[total - coin] + 1 < table[total]:
                table[total] = table[total - coin] + 1
    return -1 if table[amount] > amount else table[amount]

bruteForceCode:
def coin_change(coins, amount):
    best = [None]
    def walk(remaining, used):
        if remaining == 0:
            if best[0] is None or used < best[0]:
                best[0] = used
            return
        for coin in coins:
            if coin <= remaining:
                walk(remaining - coin, used + 1)
    walk(amount, 0)
    return -1 if best[0] is None else best[0]
